USE BWSdb
GO

-- 2024-04-19 ITI Inventory mass input and check up.
-- Nearly all of the items on this list were in my office or already in the server room.

DECLARE @changeLog TABLE ([ID] INT IDENTITY(0, 1), [Serial] NVARCHAR(MAX))
;

SELECT
	*
FROM
	[ITI Inventory] [I]
LEFT JOIN
	[ITI Locations] [L]
ON
	[I].[ITLocation] = [L].[ID]
INNER JOIN
	@changeLog [C]
ON
	[I].[ITSerial] = [C].[Serial]